#include "nexusdata/dataset/image_folder.hpp"
#include "nexusdata/dataset/map.hpp"
#include "nexusdata/pipeline/image.hpp"
#include "nexusdata/loading/dataloader.hpp"

nexusdata::ImageFolder folder("data/train");
auto mapped = nexusdata::MapDataset(
    std::move(folder),
    std::make_shared<nexusdata::Compose>({
        std::make_shared<nexusdata::Resize>(224, 224),
        std::make_shared<nexusdata::NormalizeImage>(
            std::vector<float>{0.485f, 0.456f, 0.406f},
            std::vector<float>{0.229f, 0.224f, 0.225f}),
    }));
nexusdata::DataLoaderOptions opt;
opt.batch_size = 16;
opt.shuffle = true;
opt.seed = 7;
nexusdata::DataLoader loader(std::move(mapped), opt);

